    be used in or as HTML.
    """
def html_encode(text: Any) -> object {
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;');
}

"""filter planes by the criteria specified by removeDirection
    and percentile

    Args:
        feature_dict (dictionary): planes and respective feature value
        removeDirection (string): remove above or below percentile
        percentile (int): cutoff percentile

    Returns:
        set: planes that fit the criteria
    """
def filter_planes(feature_dict: Any, removeDirection: Any, percentile: Any) -> object {
    planes = `list(feature_dict.keys());
    feat_value = [feature_dict[i] for i in planes];
    thresh = min(feat_value) + (percentile * (max(feat_value) - min(feat_value)));
    if (removeDirection == 'Below') {
        keep_planes = [
            z
            for z in planes
            if (feature_dict[z] >= thresh)
        ];
    } else {
        keep_planes = [
            z
            for z in planes
            if (feature_dict[z] <= thresh)
        ];
    }
    return `set(keep_planes);
}

"""Process to obtain the electrode name from the channel name.
    Parameters
    ----------
    channel_names : list
        Channel names in the EEG.

    Returns
    -------
    channel_names : list
        Proccessed channel names, containing only the name of the electrode.
    """
def process_channel_names(channel_names: Any) -> object {
    channel_names = [elem.split()[-1] for elem in channel_names];
    channel_names = [elem.replace("-", " ").split()[0] for elem in channel_names];
    return channel_names;
}

